</main></div><script>
const names={home:'Dashboard',sales:'Sales / POS',purchase:'Purchase',returns:'Sales Return / Exchange',products:'Item Master',customers:'Customers',vendors:'Vendors / Suppliers',stores:'Multi Store',inventory:'Inventory Transactions',accounting:'Accounting',reports:'Reports & Charts',settings:'System Customisation'};
function go(id){document.querySelectorAll('.view').forEach(x=>x.classList.remove('on'));document.getElementById(id).classList.add('on');document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('on',x.dataset.v===id));document.getElementById('title').textContent=names[id]||'Dashboard'}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>go(b.dataset.v));
const products=[['👟','Everyday Runner Shoes',1499,'Style Street'],['🎧','Wireless Headphones',2199,'Tech Corner'],['👜','Everyday Tote Bag',899,'Urban Mart'],['🪴','Minimal Plant Pot',549,'HomeNest'],['⌚','Smart Watch',3299,'Tech Corner'],['👕','Cotton Overshirt',1299,'Urban Mart'],['🧴','Body Lotion',399,'Urban Mart'],['🍳','Nonstick Pan',1199,'HomeNest']];let bill=[];
function drawItems(q=''){document.getElementById('items').innerHTML=products.filter(p=>!q||p[1].toLowerCase().includes(q.toLowerCase())).map((p,i)=>`<div class="item" onclick="add(${i})"><div class="pic">${p[0]}</div><b>${p[1]}</b><small>${p[3]} · ₹${p[2].toLocaleString('en-IN')}</small></div>`).join('')};function add(i){let a=bill.find(x=>x.i===i);a?a.q++:bill.push({i,q:1});drawBill()};function change(i,d){let a=bill.find(x=>x.i===i);if(!a)return;a.q+=d;if(a.q<1)bill=bill.filter(x=>x.i!==i);drawBill()};function drawBill(){let total=bill.reduce((s,a)=>s+products[a.i][2]*a.q,0);document.getElementById('billLines').innerHTML=bill.length?bill.map(a=>`<div class="line"><span>${products[a.i][1]}<br><small>₹${products[a.i][2]}</small></span><span class="qty"><button onclick="change(${a.i},-1)">−</button>${a.q}<button onclick="change(${a.i},1)">+</button></span><b>₹${(products[a.i][2]*a.q).toLocaleString('en-IN')}</b></div>`).join(''):'<p class="footnote">No items. Scan barcode or tap an item.</p>';document.getElementById('sub').textContent='₹'+total.toLocaleString('en-IN');document.getElementById('total').textContent='₹'+total.toLocaleString('en-IN')};function clearBill(){bill=[];drawBill()};function pay(){if(!bill.length)return alert('Add item to the invoice first.');alert('Payment completed — invoice ready to print/email.');clearBill()};document.getElementById('itemSearch').addEventListener('input',e=>drawItems(e.target.value));document.getElementById('search').addEventListener('input',e=>{let q=e.target.value.toLowerCase();if(q)go('products')});drawItems();drawBill();
</script></body></html>